namespace ghidra.program.model.data;

using ghidra.docking.settings;
using ghidra.docking.settings;
using ghidra.program.model.lang;
using ghidra.program.model.mem;

/**
 *  SettingsDefinition for endianness
 */
public class EndianSettingsDefinition : EnumSettingsDefinition {

	private static readonly string[] choices = new string[] { "default", "little", "big" };
	private static readonly string ENDIAN_SETTING_NAME = "endian";

	public static readonly EndianSettingsDefinition DEF = new EndianSettingsDefinition();
	public static readonly EndianSettingsDefinition ENDIAN = DEF;
	public static readonly int DEFAULT = 0;
	public static readonly int LITTLE = 1;
	public static readonly int BIG = 2;

	/**
	 * Constructs a new EndianSettingsDefinition
	 */
	private EndianSettingsDefinition() {
	}

	/**
	 * Returns the endianness settings.  First looks in settings, then defaultSettings
	 * and finally returns a default value if the first two have no value for this definition.
	 * @param settings the instance settings to search for the value
	 * @param buf the data context
	 * @return a boolean value for the endianness setting
	 */
	public bool isBigEndian(Settings settings, MemBuffer buf) {
		int val = getChoice(settings);
		if (val == DEFAULT) {
			return buf.isBigEndian();
		}
		return val == BIG;
	}

	public Endian getEndianness(Settings settings, Endian defaultValue) {
		int val = getChoice(settings);
		switch (val) {
			default:
			case DEFAULT:
				return defaultValue;
			case BIG:
				return Endian.BIG;
			case LITTLE:
				return Endian.LITTLE;
		}
	}

	public void setBigEndian(Settings settings, bool isBigEndian) {
		setChoice(settings, isBigEndian ? BIG : LITTLE);
	}

	/* @Override */
	public int getChoice(Settings settings) {
		if (settings == null) {
			return DEFAULT;
		}
		Long value = settings.getLong(ENDIAN_SETTING_NAME);
		if (value == null) {
			return DEFAULT;
		}
		int val = value.intValue();
		if (val < DEFAULT || val > BIG) {
			val = DEFAULT;
		}
		return val;
	}

	/* @Override */
	public string getValueString(Settings settings) {
		return choices[getChoice(settings)];
	}

	/* @Override */
	public void setChoice(Settings settings, int value) {
		settings.setLong(ENDIAN_SETTING_NAME, value);
	}

	/* @Override */
	public string[] getDisplayChoices(Settings settings) {
		return choices;
	}

	/* @Override */
	public string getName() {
		return "Endian";
	}

	/* @Override */
	public string getStorageKey() {
		return ENDIAN_SETTING_NAME;
	}

	/* @Override */
	public string getDescription() {
		return "Selects the endianness of the data";
	}

	/* @Override */
	public string getDisplayChoice(int value, Settings settings) {
		return choices[value];
	}

	/* @Override */
	public void clear(Settings settings) {
		settings.clearSetting(ENDIAN_SETTING_NAME);

	}

	/* @Override */
	public void copySetting(Settings settings, Settings destSettings) {
		Long l = settings.getLong(ENDIAN_SETTING_NAME);
		if (l == null) {
			destSettings.clearSetting(ENDIAN_SETTING_NAME);
		}
		else {
			destSettings.setLong(ENDIAN_SETTING_NAME, l);
		}
	}

	/* @Override */
	public bool hasValue(Settings setting) {
		return setting.getValue(ENDIAN_SETTING_NAME) != null;
	}

}
